/**
 * Request identity and the correlation id a developer quotes to support.
 *
 * ── REQUEST IDENTITY IS NOT IDEMPOTENCY ──
 *
 * They solve different problems and are deliberately separate. A request id
 * identifies ONE attempt, is generated by Alloy, and exists so a specific line in
 * a log can be found. An idempotency key identifies one INTENT, is generated by
 * the caller, and exists so a retry does not duplicate an effect. Collapsing them
 * would make a retried request either unfindable or non-idempotent depending on
 * which meaning won.
 *
 * A caller may supply its own correlation value and it is echoed back, but it can
 * never overwrite the canonical request id — an identifier the caller controls is
 * not one support can trust to be unique.
 */

import { createHash, randomUUID } from "crypto";

export const REQUEST_ID_HEADER = "X-Request-Id";
export const CORRELATION_HEADER = "X-Correlation-Id";

/** Bounded, and never interpreted — echoed only. */
const MAX_CORRELATION_LENGTH = 128;

export type RequestIdentity = {
    /** Server-generated. Authoritative. */
    requestId: string;
    /** Caller-supplied, sanitised, optional. Never used as identity. */
    correlationId: string | null;
};

export function resolveRequestIdentity(headers: Headers): RequestIdentity {
    const raw = (headers.get(CORRELATION_HEADER) ?? "").trim();
    const correlationId =
        raw && raw.length <= MAX_CORRELATION_LENGTH && /^[A-Za-z0-9._:-]+$/.test(raw) ? raw : null;

    return { requestId: `req_${randomUUID().replace(/-/g, "")}`, correlationId };
}

export function identityHeaders(identity: RequestIdentity): Record<string, string> {
    return {
        [REQUEST_ID_HEADER]: identity.requestId,
        ...(identity.correlationId ? { [CORRELATION_HEADER]: identity.correlationId } : {}),
    };
}

/**
 * A stable, non-reversible client identifier for rate-limit keying.
 *
 * Hashed, because the limiter table is written on every request and must not
 * become a place addresses accumulate.
 */
export function clientIpHash(headers: Headers): string {
    const forwarded = (headers.get("x-forwarded-for") ?? "").split(",")[0]?.trim();
    const ip = forwarded || headers.get("x-real-ip") || "unknown";
    return createHash("sha256").update(ip, "utf8").digest("hex").slice(0, 32);
}
